# Cloudflare Worker env name = framework vault alias.
# Applied by core/scripts/secrets-sync-to-cloudflare.sh. Values never live here.
#
# SUPABASE_SERVICE_ROLE_KEY has NO NEXT_PUBLIC_ twin, deliberately: a NEXT_PUBLIC_
# variable is inlined into the client bundle by Next at build time, so a twin would ship
# an RLS-bypassing key to every visitor. __tests__/secrets-map.test.ts asserts it, and
# e2e/smoke.spec.ts asserts it again against what actually shipped.
NEXT_PUBLIC_SUPABASE_URL      = kmp-remote-config-supabase-url
NEXT_PUBLIC_SUPABASE_ANON_KEY = kmp-remote-config-supabase-anon-key
SUPABASE_SERVICE_ROLE_KEY     = kmp-remote-config-supabase-service-role-key

# NOTE (ruling, 2026-10-06): @cloudflare/next-on-pages is intentionally NOT a
# devDependency. Its peer range is `next >=14.3.0 <=15.5.2`, which conflicts with the
# production-proven next@14.2.35 pin. `pages:build` invokes it as
# `npx @cloudflare/next-on-pages@1` — fetched at build time, never from node_modules —
# which is exactly how PayCraft builds today, so the entry bought nothing and cost an
# unresolvable install.
